  "prediction_basis_card_ids": ["C04", "C22", "C39", "C05", "C13", "C28", "C37", "C25", "C34", "C03", "C09"],
  "claims": [
    {
      "claim": "In fasted healthy subjects, esaxerenone, which bears the same 4-methylsulfonylphenyl motif as the query, had absolute oral bioavailability of 89.0% (90% CI 86.7-91.5) after a 5 mg oral tablet, directly supporting F >= 20% for this sulfone-aryl class.",
      "card_ids": ["C04", "C22", "C39"]
    },
    {
      "claim": "In fasted healthy participants, BI 425809, also bearing a 4-methylsulfonylphenyl group, had absolute oral bioavailability of 71.64% (90% CI 64.3-79.9) for a 25 mg tablet, directly supporting F >= 20% under fasted conditions.",
      "card_ids": ["C05", "C13", "C28", "C37"]
    },
    {
      "claim": "Odanacatib, which contains a directly attached 4-methylsulfonylphenyl group similar to the query, had absolute oral bioavailability of 70% at 10 mg fasted and 30% at 50 mg fasted; both values are above the 20% threshold, although F is dose-dependent.",
      "card_ids": ["C25", "C34", "C03", "C09"]
    },
    {
      "claim": "Other human oral bioavailability records, including basmisanil ~75% and pradigastat ~40% or complete, are also above the 20% threshold and provide weaker but consistent support.",
      "card_ids": ["C32", "C14", "C19", "C20"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "high",
